const b = $json.body || $json;
if (b.action !== 'created' || !b.issue || !b.comment) return [];
const text = (b.comment.body || '').trim();
const match = text.match(/^\/agent\s+(run|revise|status)\b([\s\S]*)/i);
if (!match) return [];
const association = b.comment.author_association;
if (!['OWNER', 'MEMBER', 'COLLABORATOR'].includes(association)) return [];
const labels = (b.issue.labels || []).map((label) => label.name || label);
const routes = {
  'agent:pm': 'project-manager',
  'agent:frontend': 'frontend-designer',
  'agent:content': 'content-writer',
  'agent:review': 'content-reviewer',
  'agent:seo': 'seo-geo-specialist',
};
const agent = Object.entries(routes).find(([label]) => labels.includes(label))?.[1] || 'project-manager';
return [{ json: {
  repo: b.repository.full_name,
  issue: b.issue.number,
  agent,
  command: match[1].toLowerCase(),
  notes: (match[2] || '').trim() || text,
  commentId: b.comment.id,
  issueUrl: b.issue.html_url,
} }];

const data = $json;
const result = data.result || {};
const source = $('Validate command').item.json;
let body;
if (result.ok && result.comment) {
  body = result.comment;
} else if (result.ok && result.prUrl) {
  const checks = (result.checks || []).map((check) => '- ' + check.command + ' (exit ' + check.code + ')').join('\n');
  body = 'Draft PR opened: ' + result.prUrl + '\n\nChecks run before push:\n' + checks;
} else {
  const logs = result.logs ? String(result.logs).slice(-6000) : '';
  body = 'Agent run for **' + source.agent + '** failed' + (result.phase ? ' at **' + result.phase + '**' : '') + '.\n\n' + (result.error || '') + (logs ? '\n\n```\n' + logs + '\n```' : '');
}
return [{ json: { body, agent: source.agent, issue: source.issue, repo: source.repo } }];
